using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;

namespace TradeBlotter.Api.Data;

public sealed class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Trade> Trades => Set<Trade>();

    // SQLite drops DateTimeKind; every stored DateTime is UTC, so mark reads as UTC to keep the Z on serialization.
    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder) =>
        configurationBuilder.Properties<DateTime>().HaveConversion<UtcDateTimeConverter>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var trade = modelBuilder.Entity<Trade>();
        trade.HasKey(t => t.Id);
        trade.Property(t => t.Symbol).HasMaxLength(10);
        trade.Property(t => t.Side).HasConversion<string>().HasMaxLength(4);
        trade.HasIndex(t => t.Timestamp);
    }
}

internal sealed class UtcDateTimeConverter()
    : ValueConverter<DateTime, DateTime>(v => v, v => DateTime.SpecifyKind(v, DateTimeKind.Utc));
namespace TradeBlotter.Api.Data;

public enum Side
{
    Buy,
    Sell,
}
namespace TradeBlotter.Api.Data;

public sealed class Trade
{
    public Guid Id { get; set; }
    public required string Symbol { get; set; }
    public Side Side { get; set; }
    public decimal Quantity { get; set; }
    public decimal Price { get; set; }
    public DateTime Timestamp { get; set; }
}
using Microsoft.EntityFrameworkCore;
using TradeBlotter.Api.Data;

namespace TradeBlotter.Api.Features.Trades;

public sealed class TradeService(AppDbContext db, TimeProvider clock)
{
    // Expects a request that passed model validation, including TradeValidator.
    public async Task<TradeResponse> CreateAsync(CreateTradeRequest request, CancellationToken ct)
    {
        var trade = new Trade
        {
            Id = Guid.NewGuid(),
            Symbol = TradeValidator.NormalizeSymbol(request.Symbol!),
            Side = TradeValidator.ParseSide(request.Side!),
            Quantity = request.Quantity!.Value,
            Price = request.Price!.Value,
            Timestamp = clock.GetUtcNow().UtcDateTime,
        };
        db.Trades.Add(trade);
        await db.SaveChangesAsync(ct);
        return ToResponse(trade);
    }

    public async Task<IReadOnlyList<TradeResponse>> ListAsync(CancellationToken ct) =>
        await db
            .Trades.AsNoTracking()
            .OrderByDescending(t => t.Timestamp)
            .ThenByDescending(t => t.Id)
            .Select(t => ToResponse(t))
            .ToListAsync(ct);

    public async Task<TradeResponse?> GetAsync(Guid id, CancellationToken ct) =>
        await db
            .Trades.AsNoTracking()
            .Where(t => t.Id == id)
            .Select(t => ToResponse(t))
            .SingleOrDefaultAsync(ct);

    private static TradeResponse ToResponse(Trade t) =>
        new(t.Id, t.Symbol, t.Side, t.Quantity, t.Price, t.Timestamp);
}
using TradeBlotter.Api.Data;

namespace TradeBlotter.Api.Features.Positions;

// Average-cost positions, unrounded.
public static class PositionCalculator
{
    public static IReadOnlyList<Position> Calculate(IEnumerable<Trade> trades)
    {
        var positions = new Dictionary<string, (decimal Net, decimal Avg)>();
        foreach (var trade in trades.OrderBy(t => t.Timestamp).ThenBy(t => t.Id))
        {
            var (net, avg) = positions.GetValueOrDefault(trade.Symbol);
            positions[trade.Symbol] = Apply(net, avg, trade);
        }

        return positions
            .Where(p => p.Value.Net != 0)
            .OrderBy(p => p.Key, StringComparer.Ordinal)
            .Select(p => new Position(p.Key, p.Value.Net, p.Value.Avg))
            .ToList();
    }

    private static (decimal Net, decimal Avg) Apply(decimal net, decimal avg, Trade trade)
    {
        var q = trade.Quantity;
        var signed = trade.Side == Side.Buy ? q : -q;
        var newNet = net + signed;
        var held = Math.Abs(net);

        if (net == 0 || Math.Sign(net) == Math.Sign(signed))
            return (newNet, (held * avg + q * trade.Price) / (held + q));
        // Reducing keeps the average; flipping through zero opens at this trade's price.
        // Closing to exactly zero keeps a stale average, which the next trade ignores because held is 0.
        return (newNet, q <= held ? avg : trade.Price);
    }
}
using Microsoft.EntityFrameworkCore;
using TradeBlotter.Api.Data;

namespace TradeBlotter.Api.Features.Positions;

public sealed class PositionService(AppDbContext db)
{
    // Six places survive JavaScript's number parsing; the calculator itself stays unrounded.
    private const int AverageCostDecimals = 6;

    // SQLite can't sum or order decimals, so positions are computed in memory over all trades.
    public async Task<IReadOnlyList<PositionResponse>> ListAsync(CancellationToken ct)
    {
        var trades = await db.Trades.AsNoTracking().ToListAsync(ct);
        return PositionCalculator
            .Calculate(trades)
            .Select(p => new PositionResponse(
                p.Symbol,
                p.NetQuantity,
                Math.Round(p.AverageCost, AverageCostDecimals, MidpointRounding.AwayFromZero)
            ))
            .ToList();
    }
}
using TradeBlotter.Api.Data;

namespace TradeBlotter.Api.Features.Trades;

public sealed record TradeResponse(
    Guid Id,
    string Symbol,
    Side Side,
    decimal Quantity,
    decimal Price,
    DateTime Timestamp
);
using System.Text.Json.Serialization;
using Microsoft.EntityFrameworkCore;
using Microsoft.OpenApi.Models;
using TradeBlotter.Api.Data;
using TradeBlotter.Api.Features.Positions;
using TradeBlotter.Api.Features.Trades;
using TradeBlotter.Api.Http;

var builder = WebApplication.CreateBuilder(args);

builder
    .Services.AddControllers()
    .AddJsonOptions(o =>
    {
        o.JsonSerializerOptions.Converters.Add(
            new JsonStringEnumConverter(allowIntegerValues: false)
        );
        // The contract sends money as JSON numbers; reject "100" instead of coercing it.
        o.JsonSerializerOptions.NumberHandling = JsonNumberHandling.Strict;
    })
    .ConfigureApiBehaviorOptions(o =>
        o.InvalidModelStateResponseFactory = ValidationProblemFactory.Create
    );
builder.Services.AddProblemDetails();
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(o =>
{
    o.SupportNonNullableReferenceTypes();
    o.SchemaFilter<SideSchemaFilter>();
    o.SchemaFilter<ResponseSchemaFilter>();
    // Swashbuckle maps decimal to "double"; money is decimal end to end.
    o.MapType<decimal>(() => new OpenApiSchema { Type = "number", Format = "decimal" });
    o.MapType<decimal?>(() =>
        new OpenApiSchema
        {
            Type = "number",
            Format = "decimal",
            Nullable = true,
        }
    );
});

builder.Services.AddDbContext<AppDbContext>(o =>
    o.UseSqlite(builder.Configuration.GetConnectionString("TradeBlotter"))
);
builder.Services.AddSingleton(TimeProvider.System);
builder.Services.AddScoped<TradeService>();
builder.Services.AddScoped<PositionService>();

var app = builder.Build();

using (var scope = app.Services.CreateScope())
{
    scope.ServiceProvider.GetRequiredService<AppDbContext>().Database.EnsureCreated();
}

app.UseExceptionHandler();
app.UseStatusCodePages();

if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.MapControllers();

app.Run();

