import { test } from '@playwright/test'
import { fillTrade, openEntry } from './blotter'

type W = { log: string[]; t0: number }

test('probe focus timing', async ({ page }) => {
  await page.goto('/')
  await page.evaluate(() => {
    const w = window as unknown as W
    w.log = []
    w.t0 = performance.now()
    const t = () => Math.round(performance.now() - w.t0)
    document.addEventListener(
      'focusin',
      (e) => {
        const el = e.target as HTMLElement
        w.log.push(`${t()}ms focusin ${el.id || el.getAttribute('aria-label') || el.tagName}`)
      },
      true,
    )
    document.addEventListener(
      'keydown',
      (e) => w.log.push(`${t()}ms key ${e.key} -> ${(document.activeElement as HTMLElement).id}`),
      true,
    )
  })
  for (let i = 0; i < 5; i++) {
    await page.evaluate(() => {
      const w = window as unknown as W
      w.t0 = performance.now()
      w.log.push('--- open')
    })
    const dialog = await openEntry(page)
    await fillTrade(dialog, { symbol: 'PROBE', side: 'Buy', quantity: 150, price: 12 })
    const vals = await dialog
      .locator('input')
      .evaluateAll((els) => els.map((e) => (e as HTMLInputElement).value))
    await page.evaluate((v) => (window as unknown as W).log.push(`values ${JSON.stringify(v)}`), vals)
    await dialog.getByRole('button', { name: 'Cancel' }).click()
    await page.waitForTimeout(500)
  }
  console.log((await page.evaluate(() => (window as unknown as W).log)).join('\n'))
})

