import { expect, test } from '@playwright/test'
import { addTrade, expectPosition } from './blotter'

// Throwaway amplifier: the oversell flow, many times per page.
test.setTimeout(0)

for (let round = 0; round < Number(process.env.ROUNDS ?? 10); round++) {
  test(`oversell round ${round}`, async ({ page }) => {
    if (process.env.E2E_CPU) {
      const cdp = await page.context().newCDPSession(page)
      await cdp.send('Emulation.setCPUThrottlingRate', { rate: Number(process.env.E2E_CPU) })
    }
    await page.goto('/')
    for (let i = 0; i < 10; i++) {
      const symbol = `H${round}X${i}`
      await addTrade(page, { symbol, side: 'Buy', quantity: 100, price: 10 })
      await addTrade(page, { symbol, side: 'Sell', quantity: 150, price: 12 })
      await expectPosition(page, symbol, '-50', '12.00')
    }
    expect(true).toBe(true)
  })
}

